import Vue from "vue";
import VueRouter from "vue-router";
import HomeView from "../views/HomeView.vue";
import People from "../views/People.vue";
import Research from "../views/Research.vue";
import ResearchDirection from "../views/ResearchDirection.vue";
import News from "../views/News.vue";
import NewsDetail from "../views/NewsDetail.vue";
import Contact from "../views/Contact.vue";
import Application from "../views/Application.vue";
import BrandAssets from "../views/BrandAssets.vue";
Vue.use(VueRouter);

const routes = [
  {
    path: "/",
    name: "home",
    component: HomeView,
  },
  {
    path: "/people",
    name: "people",
    component: People,
  },
  {
    path: "/research",
    name: "research",
    component: Research,
  },
  {
    path: "/research/directions/:tagId",
    name: "research-direction",
    component: ResearchDirection,
  },
  {
    path: "/news",
    name: "news",
    component: News,
  },
  {
    path: "/news/:id",
    name: "news-detail",
    component: NewsDetail,
  },
  {
    path: "/contact",
    name: "contact",
    component: Contact,
  },
  {
    path: "/application",
    name: "application",
    component: Application,
  },
  {
    path: "/vi",
    name: "brand-assets",
    component: BrandAssets,
  },
];

const router = new VueRouter({
  // mode: "history",
  base: process.env.BASE_URL,
  routes,
  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) {
      return savedPosition;
    }

    if (to.name === "research" && from.name === "research") {
      return false;
    }

    return { x: 0, y: 0 };
  },
});

export default router;
